package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w360dp-h780dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class WidgetV088Test {
 private Context c;
 @Before public void start(){c=RuntimeEnvironment.getApplication();AppState.setRegion(c,Region.CHINA);c.getSharedPreferences("preferences",0).edit().clear().commit();c.getSharedPreferences("climate_runtime_v1",0).edit().clear().commit();AppPreferences.set(c,"widget_language","en");}
 private VehicleSnapshot snapshot(String climate,Integer minutes,long ago){long now=System.currentTimeMillis();return new VehicleSnapshot("Polestar 2 Long Range Dual Motor","masked",99,456,765432,"充电中","全部关闭","全部关闭","已关闭","已上锁",now,"LIVE",false,climate,"关闭").withHealth(new VehicleHealthSnapshot(1,1,1,now,1,1,1,-1,1,931,75,14959)).withEnvironment(new EnvironmentSnapshot(climate,"关闭",23.0,22.0,3.0,4,minutes,0,now-ago,now)).withMileage(new MileageSnapshot(765432000L,9999.9,9999.9,128.0,125.0,18.8,19.2,now,now)).withCharging(new ChargingSnapshot(1,2,4,180,6000.0,29.0));}
 private View widget(String design,WidgetRenderer.Size size,int width,int height,VehicleSnapshot s){AppPreferences.set(c,"widget_design",design);View v=WidgetRenderer.createViews(c,88,size,width,height,null,s).apply(c,new FrameLayout(c));v.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));v.layout(0,0,width,height);return v;}
 private void fit(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.length()>0&&t.getLayout()!=null){String info="id="+v.getId()+" text="+t.getText()+" w="+t.getWidth()+" h="+t.getHeight()+" layout="+t.getLayout().getHeight();assertFalse(info,t.getText().toString().contains("…")||t.getText().toString().contains("..."));assertTrue(info,t.getLayout().getHeight()<=t.getHeight()-t.getCompoundPaddingTop()-t.getCompoundPaddingBottom());for(int i=0;i<t.getLayout().getLineCount();i++){assertEquals(info,0,t.getLayout().getEllipsisCount(i));assertTrue(info+" line="+t.getLayout().getLineWidth(i),t.getLayout().getLineWidth(i)<=t.getWidth()-t.getCompoundPaddingLeft()-t.getCompoundPaddingRight()+1);}}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View child=g.getChildAt(i);if(child.getVisibility()==View.GONE)continue;assertTrue("child below parent "+child.getId(),child.getBottom()<=g.getHeight()+1);assertTrue("child beyond parent "+child.getId(),child.getRight()<=g.getWidth()+1);fit(child);}}}
 @Test public void stableFanAndColorFollowReportedStateAcrossAllStylesAndSizes(){for(String design:new String[]{"classic","volike_simple","volike_detailed","volike_polestar","pseu"})for(WidgetRenderer.Size size:WidgetRenderer.Size.values()){WidgetButtons.save(c,size,Arrays.asList("lock","climate"));for(String state:new String[]{"开启","关闭","未知"}){View v=widget(design,size,WidgetRenderer.defaultWidth(size),WidgetRenderer.defaultHeight(size),snapshot(state,18,0));ImageView icon=v.findViewById(R.id.widget_climate_icon);assertEquals(design+size+state,R.drawable.ic_climate,Shadows.shadowOf(icon.getDrawable()).getCreatedFromResId());TextView text=v.findViewById(R.id.widget_climate_label);assertEquals(state.equals("开启")?"18m":"Climate",text.getText().toString());int color=((android.graphics.drawable.GradientDrawable)v.findViewById(R.id.widget_action_climate).getBackground()).getColor().getDefaultColor();assertEquals(state.equals("开启"),color==PsaDesign.ORANGE);}}}
 @Test public void remainingTimeUsesReportThenConfirmedLocalFallbackAndNeverChangesVehicleState(){WidgetRenderer.Size size=WidgetRenderer.Size.LARGE;WidgetButtons.save(c,size,Arrays.asList("climate"));for(int age:new int[]{0,60_000,19*60_000}){VehicleSnapshot s=snapshot("开启",18,age);View v=widget("pseu",size,300,170,s);assertEquals(age==0?"18m":age==60_000?"17m":"0m",((TextView)v.findViewById(R.id.widget_lock_label)).getText().toString());assertEquals("开启",s.climate);}View v=widget("classic",size,300,170,snapshot("开启",null,0));assertEquals("--m",((TextView)v.findViewById(R.id.widget_lock_label)).getText().toString());AppPreferences.set(c,"vehicle","fixture");ClimateRuntime.started(c,"fixture",System.currentTimeMillis());v=widget("classic",size,300,170,snapshot("开启",null,0));assertEquals("30m",((TextView)v.findViewById(R.id.widget_lock_label)).getText().toString());}
 @Test public void fixedStartAndStopKeepTheirActionNamesWithTheSameGlyph(){WidgetRenderer.Size size=WidgetRenderer.Size.LARGE;WidgetButtons.save(c,size,Arrays.asList("climate-start","climate-stop"));View v=widget("pseu",size,300,170,snapshot("开启",18,0));assertEquals("Start 18m",((TextView)v.findViewById(R.id.widget_lock_label)).getText().toString());assertEquals("Stop 18m",((TextView)v.findViewById(R.id.widget_climate_label)).getText().toString());assertEquals(R.drawable.ic_climate,Shadows.shadowOf(((ImageView)v.findViewById(R.id.widget_lock_icon)).getDrawable()).getCreatedFromResId());assertEquals(R.drawable.ic_climate,Shadows.shadowOf(((ImageView)v.findViewById(R.id.widget_climate_icon)).getDrawable()).getCreatedFromResId());}
 @Test public void allNativeTextFitsWithoutEllipsesAtLargeFontAndNarrowSizes(){AppPreferences.set(c,"widget_font_percent","120");AppPreferences.set(c,"widget_bold","on");String[] designs={"classic","volike_simple","volike_detailed","volike_polestar","pseu"};for(float scale:new float[]{1f,1.3f,1.56f}){Configuration config=new Configuration(c.getResources().getConfiguration());config.fontScale=scale;android.util.DisplayMetrics dm=c.getResources().getDisplayMetrics();dm.scaledDensity=scale;c.getResources().updateConfiguration(config,dm);for(String lang:new String[]{"zh","en"}){AppPreferences.set(c,"widget_language",lang);for(String design:designs)for(WidgetRenderer.Size size:WidgetRenderer.Size.values()){AppPreferences.set(c,"widget_design",design);MetricSelection.save(c,WidgetRenderer.selectionKey(c,size),Arrays.asList(DisplayMetric.BATTERY,DisplayMetric.RANGE,DisplayMetric.VEHICLE_STATUS,DisplayMetric.ODOMETER,DisplayMetric.SERVICE_KM_LEFT,DisplayMetric.TM_DISTANCE,DisplayMetric.TA_CONSUMPTION,DisplayMetric.PM25));AppPreferences.set(c,"pseu_"+WidgetRenderer.metricKey(size),"battery,range,vehicle_status,odometer,service_km_left,tm_distance,ta_consumption,pm25");WidgetButtons.save(c,size,Arrays.asList("lock","climate","air","trunk","windows"));int w=size==WidgetRenderer.Size.MINI?118:WidgetRenderer.defaultWidth(size),h=WidgetRenderer.defaultHeight(size);try{fit(widget(design,size,w,h,snapshot("开启",18,0)));}catch(AssertionError e){throw new AssertionError(design+" "+size+" "+lang+" font="+scale,e);}}}}}
 @Test public void chargingAndResizedStripsKeepFullValuesWithoutOverlap(){AppPreferences.set(c,"widget_font_percent","120");AppPreferences.set(c,"widget_bold","on");Configuration config=new Configuration(c.getResources().getConfiguration());config.fontScale=1.56f;android.util.DisplayMetrics dm=c.getResources().getDisplayMetrics();dm.scaledDensity=1.56f;c.getResources().updateConfiguration(config,dm);for(String design:new String[]{"classic","volike_simple","volike_detailed","volike_polestar","pseu"})for(int[] bounds:new int[][]{{250,70},{269,51},{320,70},{380,70},{300,170}}){AppPreferences.set(c,"widget_design",design);WidgetRenderer.Size size=bounds[1]>100?WidgetRenderer.Size.LARGE:WidgetRenderer.Size.EXTRA_WIDE;MetricSelection.save(c,WidgetRenderer.selectionKey(c,size),Arrays.asList(DisplayMetric.BATTERY,DisplayMetric.RANGE,DisplayMetric.CHARGE_POWER,DisplayMetric.CHARGE_CURRENT,DisplayMetric.CHARGE_ETA,DisplayMetric.CHARGE_CONNECTION,DisplayMetric.CHARGE_TYPE,DisplayMetric.POWER_STATUS));WidgetButtons.save(c,size,Arrays.asList("lock","climate","air","trunk","windows"));try{fit(widget(design,size,bounds[0],bounds[1],snapshot("开启",18,0)));}catch(AssertionError e){throw new AssertionError(design+" "+Arrays.toString(bounds),e);}}}
 @Test public void exportsWideAndSmallWidgetPreviews()throws Exception{File dir=new File("build/reports/previews/v088");dir.mkdirs();for(WidgetRenderer.Size size:new WidgetRenderer.Size[]{WidgetRenderer.Size.EXTRA_WIDE,WidgetRenderer.Size.MINI,WidgetRenderer.Size.LARGE}){WidgetButtons.save(c,size,size==WidgetRenderer.Size.EXTRA_WIDE?Arrays.asList("lock","climate","air","trunk","windows"):Arrays.asList("lock","climate"));int w=WidgetRenderer.defaultWidth(size),h=WidgetRenderer.defaultHeight(size);View v=widget("pseu",size,w,h,snapshot("开启",18,0));Bitmap b=Bitmap.createBitmap(w*3,h*3,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.scale(3,3);v.draw(canvas);try(FileOutputStream out=new FileOutputStream(new File(dir,"widget-"+size.name().toLowerCase()+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}}
}
